import{describe,it,expect,beforeAll}from"vitest";import{readFileSync}from"node:fs";import{resolve,dirname}from"node:path";import{fileURLToPath}from"node:url";const __dirname=dirname(fileURLToPath(import.meta.url));function loadManasData(){const e=readFileSync(resolve(__dirname,"../../frontend/manas-national-park-explorer/manas-data.js"),"utf-8");return new Function(e+"\nreturn { MANAS_INFO, FIVE_STATUSES, MANAS_RIVER_INFO, SPECIES_SPOTLIGHT, BIRDLIFE, HISTORY_TIMELINE, INTERESTING_FACTS, MAP_HOTSPOTS, GALLERY_IMAGES };")()}function loadNationalParksData(){const e=readFileSync(resolve(__dirname,"../../frontend/national-parks-explorer/data.js"),"utf-8");return new Function(e+"\nreturn { NATIONAL_PARKS, STATES };")()}function loadSearchIndex(){const e=readFileSync(resolve(__dirname,"../../search-index.js"),"utf-8");return new Function("window",e+"\nreturn window.indiaSearchIndex;")({})}describe("Manas National Park Explorer — Data & Integration Tests",()=>{let e;beforeAll(()=>{e=loadManasData()}),describe("MANAS_INFO metadata & FIVE_STATUSES",()=>{it("contains correct park metadata for Manas",()=>{expect(e.MANAS_INFO.id).toBe("manas"),expect(e.MANAS_INFO.name).toBe("Manas National Park"),expect(e.MANAS_INFO.state).toBe("Assam"),expect(e.MANAS_INFO.unescoYear).toBe(1985),expect(e.MANAS_INFO.coordinates.lat).toBeCloseTo(26.65,2),expect(e.MANAS_INFO.coordinates.lng).toBeCloseTo(91,2)}),it("FIVE_STATUSES contains 5 conservation designations",()=>{expect(Array.isArray(e.FIVE_STATUSES)).toBe(!0),expect(e.FIVE_STATUSES.length).toBe(5);const t=e.FIVE_STATUSES.find(e=>e.title.includes("UNESCO"));expect(t).toBeDefined()})}),describe("SPECIES_SPOTLIGHT & MANAS_RIVER_INFO",()=>{it("SPECIES_SPOTLIGHT includes Golden Langur, Pygmy Hog, and Bengal Tiger",()=>{expect(Array.isArray(e.SPECIES_SPOTLIGHT)).toBe(!0),expect(e.SPECIES_SPOTLIGHT.length).toBeGreaterThanOrEqual(6);const t=e.SPECIES_SPOTLIGHT.find(e=>"golden-langur"===e.id),a=e.SPECIES_SPOTLIGHT.find(e=>"pygmy-hog"===e.id),r=e.SPECIES_SPOTLIGHT.find(e=>"bengal-tiger"===e.id);expect(t).toBeDefined(),expect(a).toBeDefined(),expect(r).toBeDefined(),expect(a.status).toContain("Critically Endangered")}),it("MANAS_RIVER_INFO details transboundary hydrology",()=>{expect(e.MANAS_RIVER_INFO.name).toContain("Manas River"),expect(e.MANAS_RIVER_INFO.origin).toContain("Bhutan"),expect(Array.isArray(e.MANAS_RIVER_INFO.keyFeatures)).toBe(!0)})}),describe("BIRDLIFE & INTERESTING_FACTS",()=>{it("BIRDLIFE has required properties and includes Bengal Florican",()=>{expect(Array.isArray(e.BIRDLIFE)).toBe(!0),expect(e.BIRDLIFE.length).toBeGreaterThanOrEqual(4);const t=e.BIRDLIFE.find(e=>"bengal-florican"===e.id);expect(t).toBeDefined(),e.BIRDLIFE.forEach(e=>{expect(e).toHaveProperty("id"),expect(e).toHaveProperty("name"),expect(e).toHaveProperty("scientificName"),expect(e).toHaveProperty("status"),expect(e).toHaveProperty("image"),expect(e).toHaveProperty("description")})}),it("INTERESTING_FACTS contains 6 cards",()=>{expect(Array.isArray(e.INTERESTING_FACTS)).toBe(!0),expect(e.INTERESTING_FACTS.length).toBe(6)})}),describe("MAP_HOTSPOTS & HISTORY_TIMELINE",()=>{it("MAP_HOTSPOTS has valid percentage coordinates (0-100)",()=>{expect(Array.isArray(e.MAP_HOTSPOTS)).toBe(!0),expect(e.MAP_HOTSPOTS.length).toBeGreaterThanOrEqual(5),e.MAP_HOTSPOTS.forEach(e=>{expect(e.x).toBeGreaterThanOrEqual(0),expect(e.x).toBeLessThanOrEqual(100),expect(e.y).toBeGreaterThanOrEqual(0),expect(e.y).toBeLessThanOrEqual(100)})}),it("HISTORY_TIMELINE includes 2011 UNESCO Danger List removal",()=>{expect(Array.isArray(e.HISTORY_TIMELINE)).toBe(!0);const t=e.HISTORY_TIMELINE.find(e=>e.year.includes("2011"));expect(t).toBeDefined()})}),describe("Landing Page & Search Index Integration",()=>{it("Manas entry in NATIONAL_PARKS has explorerUrl",()=>{const e=loadNationalParksData().NATIONAL_PARKS.find(e=>"manas"===e.id);expect(e).toBeDefined(),expect(e.explorerUrl).toBe("../manas-national-park-explorer/index.html"),expect(e.state).toBe("Assam")}),it("Search Index registers Manas National Park Explorer",()=>{const e=loadSearchIndex().find(e=>"Manas National Park Explorer"===e.title);expect(e).toBeDefined(),expect(e.url).toBe("frontend/manas-national-park-explorer/index.html")})})});